-- Isolated fixtures only. No Google/FCM request is made; every row rolls back.
begin;
create temporary table note_test(a uuid,b uuid,c uuid,sid uuid,code text,id uuid,other uuid,device uuid);
insert into note_test values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,null,gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
insert into auth.users(id,aud,role,email) select a,'authenticated','authenticated',a::text||'@note-test.invalid' from note_test union all select b,'authenticated','authenticated',b::text||'@note-test.invalid' from note_test union all select c,'authenticated','authenticated',c::text||'@note-test.invalid' from note_test;
grant select,update on note_test to authenticated;
create function pg_temp.assert_note(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from note_test;
update note_test set sid=public.create_partner_space_with_role('user_1');
update note_test set code=public.issue_pair_code()->>'code';
select public.mutate_shared_record(id,sid,'appreciation',null,null,jsonb_build_object('kind','Message','message','Synthetic hello','taskTitle','','picture','','at',1),0,gen_random_uuid(),false) from note_test;
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true) from note_test;
select public.redeem_pair_code_with_role(code,'user_2') from note_test;
select pg_temp.assert_note((select count(*) from public.shared_records where id=(select id from note_test))=1,'paired recipient reads note');
do $$declare t record;begin select * into t from note_test;
 begin perform public.claim_note_notification(t.id,t.a);raise exception 'FAILED: client token access allowed';exception when insufficient_privilege then null;end;
 begin perform public.mutate_shared_record(t.id,t.sid,'appreciation',null,null,(select payload from public.shared_records where id=t.id),1,gen_random_uuid(),false);raise exception 'FAILED: partner edited sender note';exception when raise_exception then if SQLERRM like 'FAILED:%' then raise;end if;end;
end$$;
select public.set_poke_preferences(false,'Europe/Berlin',false,1320,450);
reset role;
select pg_temp.assert_note(public.claim_note_notification(id,c)->>'status'='unavailable','outsider rejected') from note_test;
select pg_temp.assert_note(public.claim_note_notification(id,a)->>'status'='recipient_unavailable','recipient opt-out respected') from note_test;
set local role authenticated;
select public.set_poke_preferences(true,'Europe/Berlin',false,1320,450);
reset role;
select pg_temp.assert_note(public.claim_note_notification(id,a)->>'status'='no_device','missing device handled') from note_test;
set local role authenticated;
select public.register_push_device(device,'pipo-note-test-'||b::text) from note_test;
reset role;
update public.poke_preferences set quiet_enabled=true,quiet_start=(extract(hour from now() at time zone 'Europe/Berlin')::int*60+extract(minute from now() at time zone 'Europe/Berlin')::int),quiet_end=(extract(hour from now() at time zone 'Europe/Berlin')::int*60+extract(minute from now() at time zone 'Europe/Berlin')::int+1)%1440 where user_id=(select b from note_test);
select pg_temp.assert_note(public.claim_note_notification(id,a)->>'status'='recipient_unavailable','quiet hours respected') from note_test;
update public.poke_preferences set quiet_enabled=false where user_id=(select b from note_test);
update public.shared_records set updated_at=now()-interval '25 hours' where id=(select id from note_test);
select pg_temp.assert_note(public.claim_note_notification(id,a)->>'status'='unavailable','expired notes rejected') from note_test;
update public.shared_records set updated_at=now(),deleted_at=now() where id=(select id from note_test);
select pg_temp.assert_note(public.claim_note_notification(id,a)->>'status'='unavailable','deleted notes rejected') from note_test;
update public.shared_records set deleted_at=null where id=(select id from note_test);
select pg_temp.assert_note(public.claim_note_notification(id,a)->>'status'='claimed','consenting recipient claimed') from note_test;
select pg_temp.assert_note(public.claim_note_notification(id,a)->>'status'='already_sent','duplicate delivery blocked') from note_test;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from note_test;
select public.mutate_shared_record(other,sid,'appreciation',null,null,jsonb_build_object('kind','Locket','message','Photo','taskTitle','','picture','cloud:unused','at',1),0,gen_random_uuid(),false) from note_test;
reset role;
select pg_temp.assert_note(public.claim_note_notification(other,a)->>'status'='unavailable','photo notifications use separate sender') from note_test;
-- Every supported note type works; a burst stops after 20 claims per minute.
do $$declare t record; nid uuid; k text; i int;begin select * into t from note_test;
 foreach k in array array['Thank you','You''re the best','Purr-fect','CareSupport','Heart'] loop
  nid:=gen_random_uuid();perform public.mutate_shared_record(nid,t.sid,'appreciation',null,null,jsonb_build_object('kind',k,'message','Synthetic test','taskTitle','','picture','','at',1),0,gen_random_uuid(),false);
  perform pg_temp.assert_note(public.claim_note_notification(nid,t.a)->>'status'='claimed','supported note type '||k);
 end loop;
 for i in 7..20 loop
  nid:=gen_random_uuid();perform public.mutate_shared_record(nid,t.sid,'appreciation',null,null,jsonb_build_object('kind','Message','message','Rate test','taskTitle','','picture','','at',1),0,gen_random_uuid(),false);
  perform pg_temp.assert_note(public.claim_note_notification(nid,t.a)->>'status'='claimed','claim below rate limit');
 end loop;
 nid:=gen_random_uuid();perform public.mutate_shared_record(nid,t.sid,'appreciation',null,null,jsonb_build_object('kind','Message','message','Rate test','taskTitle','','picture','','at',1),0,gen_random_uuid(),false);
 perform pg_temp.assert_note(public.claim_note_notification(nid,t.a)->>'status'='rate_limited','burst rate limit enforced');
end$$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true) from note_test;
select pg_temp.assert_note((select count(*) from public.shared_records)=0,'outsider cannot read messages');
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from note_test;
select public.leave_partner_space();
reset role;
select pg_temp.assert_note(public.claim_note_notification(id,a)->>'status'='unavailable','leaving space revokes notification') from note_test;
select 'PASS: note authorization, RLS, read-only partner, opt-out, quiet hours, missing device, expiry, deletion, supported kinds, deduplication, rate limiting, unpairing' as result;
rollback;
